package io.metagen.ai;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import lombok.Data;

import java.util.List;

/**
 * Structured schema proposal generated by the AI assistant.
 *
 * <p>Claude returns a JSON object that is deserialised into this class.
 * The Studio then presents it to the user for review before any
 * metadata is persisted.</p>
 *
 * <h2>Example (from the description "gestion des fournisseurs avec commandes")</h2>
 * <pre>
 * {
 *   "entities": [
 *     {
 *       "name": "supplier",
 *       "label": "Fournisseur",
 *       "fields": [
 *         { "name": "name",  "label": "Raison sociale", "type": "STRING",  "required": true },
 *         { "name": "siret", "label": "SIRET",           "type": "STRING",  "unique": true },
 *         { "name": "email", "label": "Email",           "type": "EMAIL" }
 *       ]
 *     },
 *     {
 *       "name": "purchase_order",
 *       "label": "Bon de commande",
 *       "workflow": "order_lifecycle",
 *       "fields": [
 *         { "name": "reference", "label": "Référence", "type": "STRING", "required": true },
 *         { "name": "amount",    "label": "Montant",   "type": "DECIMAL" },
 *         { "name": "supplier",  "label": "Fournisseur", "type": "REFERENCE",
 *           "options": { "targetEntity": "supplier" } }
 *       ]
 *     }
 *   ],
 *   "workflows": [
 *     {
 *       "name": "order_lifecycle",
 *       "label": "Cycle de vie bon de commande",
 *       "states": [
 *         { "name": "DRAFT",    "label": "Brouillon",  "initial": true,  "color": "gray" },
 *         { "name": "APPROVED", "label": "Approuvé",   "terminal": false, "color": "green" },
 *         { "name": "RECEIVED", "label": "Réceptionné","terminal": true,  "color": "blue" }
 *       ],
 *       "transitions": [
 *         { "from": "DRAFT",    "to": "APPROVED", "label": "Approuver",     "requiredRole": "MANAGER" },
 *         { "from": "APPROVED", "to": "RECEIVED", "label": "Réceptionner" }
 *       ]
 *     }
 *   ],
 *   "explanation": "Deux entités liées par une FK. Workflow sur les bons de commande."
 * }
 * </pre>
 */
@Data
@JsonIgnoreProperties(ignoreUnknown = true)
public class MetaProposal {

    private List<EntityProposal>   entities    = List.of();
    private List<WorkflowProposal> workflows   = List.of();
    private String                 explanation;

    // ── Entity ────────────────────────────────────────────────────────

    @Data
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class EntityProposal {
        private String              name;
        private String              label;
        private String              description;
        private String              workflow;     // workflow name reference
        private List<FieldProposal> fields = List.of();
    }

    @Data
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class FieldProposal {
        private String              name;
        private String              label;
        private String              type;         // MetaFieldType name
        private boolean             required;
        private boolean             unique;
        private boolean             searchable = true;
        private java.util.Map<String, Object> options;
    }

    // ── Workflow ──────────────────────────────────────────────────────

    @Data
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class WorkflowProposal {
        private String              name;
        private String              label;
        private List<StateProposal>      states      = List.of();
        private List<TransitionProposal> transitions = List.of();
    }

    @Data
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class StateProposal {
        private String  name;
        private String  label;
        private boolean initial;
        private boolean terminal;
        private String  color;
    }

    @Data
    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class TransitionProposal {
        private String from;
        private String to;
        private String label;
        private String requiredRole;
    }
}
